from pathlib import Path


path = Path(__file__).resolve().parents[1] / "index.html"
html = path.read_text(encoding="utf-8")

old_css = '.geo-button{width:100%;border:1px dashed var(--raspberry);background:#fff;color:var(--raspberry-deep);padding:10px;border-radius:8px;font-size:.82rem;font-weight:800}.geo-status{display:none;margin-top:8px;padding:10px;border-radius:7px;font-size:.8rem;line-height:1.35}.geo-status.show{display:block}.geo-status.pending{background:#fff8e8;color:#6d4a05;border:1px solid #d7af5d}.geo-status.ok{background:#eaf5e9;color:#245b27;border:1px solid #83b67f}.geo-status.error{background:#fff0f5;color:#7a153b;border:2px solid var(--raspberry)}'
new_css = '.geo-button{width:100%;border:1px dashed var(--raspberry);background:#fff;color:var(--raspberry-deep);padding:10px;border-radius:8px;font-size:.82rem;font-weight:800}.geo-button:disabled{opacity:.72;cursor:wait}.geo-help{margin:8px 0 0;color:var(--ink-soft);font-size:.75rem;line-height:1.35}.geo-status{display:none;margin-top:8px;padding:10px;border-radius:7px;font-size:.8rem;line-height:1.35}.geo-status.show{display:block}.geo-status.pending{background:#fff8e8;color:#6d4a05;border:1px solid #d7af5d}.geo-status.ok{background:#eaf5e9;color:#245b27;border:1px solid #83b67f}.geo-status.error{background:#fff0f5;color:#7a153b;border:2px solid var(--raspberry)}.geo-map-link{display:none;align-items:center;justify-content:center;width:100%;min-height:42px;margin-top:9px;border:1px solid var(--green);border-radius:8px;background:#f4fbf3;color:#245b27;font-size:.8rem;font-weight:800;text-decoration:none}.geo-map-link.show{display:inline-flex}.geo-map-link:focus-visible{outline-color:var(--green)}'
if old_css not in html:
    raise SystemExit("Bloc CSS de géolocalisation introuvable.")
html = html.replace(old_css, new_css, 1)

old_markup = '<button type="button" class="geo-button" id="geoButton">Partager ma position (GPS)</button><div id="geoStatus" class="geo-status" role="status"></div><label class="field-label" for="deliveryAddress">Adresse ou point de repère</label>'
new_markup = '<button type="button" class="geo-button" id="geoButton">Partager ma position pour la livraison</button><p class="geo-help" id="geoHelp">Avec votre accord, votre position sera ajoutée uniquement au message WhatsApp. Vous pouvez aussi saisir une adresse ci-dessous.</p><div id="geoStatus" class="geo-status" role="status"></div><a id="geoMapLink" class="geo-map-link" href="#" target="_blank" rel="noopener noreferrer" hidden>Ouvrir dans Plans pour vérifier</a><label class="field-label" for="deliveryAddress">Adresse ou point de repère</label>'
if old_markup not in html:
    raise SystemExit("Bloc HTML de géolocalisation introuvable.")
html = html.replace(old_markup, new_markup, 1)

old_script = 'const geoButton=document.getElementById("geoButton"),geoStatus=document.getElementById("geoStatus");function displayGeo(type,message){geoStatus.className=`geo-status show ${type}`;geoStatus.textContent=message;geoStatus.setAttribute("role",type==="error"?"alert":"status")}geoButton.addEventListener("click",()=>{if(!navigator.geolocation){displayGeo("error","La localisation n’est pas disponible sur cet appareil. Indiquez votre adresse ci-dessous.");return}geoButton.disabled=true;displayGeo("pending","Recherche de votre position… Vous pouvez aussi saisir votre adresse manuellement.");navigator.geolocation.getCurrentPosition(position=>{const {latitude,longitude}=position.coords;geo={url:`https://maps.google.com/?q=${latitude.toFixed(6)},${longitude.toFixed(6)}`};displayGeo("ok","Position captée. Elle sera ajoutée au message WhatsApp.");geoButton.disabled=false},error=>{displayGeo("error",error.code===1?"Vous avez refusé la localisation. Votre adresse écrite suffit aussi.":"La localisation a pris trop de temps. Réessayez ou indiquez votre adresse.");geoButton.disabled=false},{enableHighAccuracy:true,timeout:10000,maximumAge:0})});'
new_script = '''const geoButton=document.getElementById("geoButton"),geoStatus=document.getElementById("geoStatus"),geoMapLink=document.getElementById("geoMapLink"),geoHelp=document.getElementById("geoHelp");const isIOS=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1);const isEmbeddedIOS=/(Instagram|FBAN|FBAV|TikTok|musical_ly|Line\/|Twitter|Snapchat)/i.test(navigator.userAgent);function displayGeo(type,message){geoStatus.className=`geo-status show ${type}`;geoStatus.textContent=message;geoStatus.setAttribute("role",type==="error"?"alert":"status")}function hideGeoMapLink(){geoMapLink.hidden=true;geoMapLink.classList.remove("show");geoMapLink.removeAttribute("href")}function showGeoMapLink(latitude,longitude){const coordinates=`${latitude.toFixed(6)},${longitude.toFixed(6)}`;geoMapLink.href=isIOS?`https://maps.apple.com/place?coordinate=${coordinates}&name=${encodeURIComponent("Position de livraison")}`:`https://www.google.com/maps/search/?api=1&query=${coordinates}`;geoMapLink.textContent=isIOS?"Ouvrir dans Plans pour vérifier":"Ouvrir la carte pour vérifier";geoMapLink.hidden=false;geoMapLink.classList.add("show")}function geoErrorMessage(error,retried){if(error.code===1)return isEmbeddedIOS?"La localisation est bloquée dans ce navigateur de réseau social. Ouvrez le site dans Safari, ou indiquez votre adresse ci-dessous.":"La localisation n’a pas été autorisée. Vous pouvez la réactiver dans Réglages, ou saisir votre adresse ci-dessous.";if(error.code===2)return "Votre iPhone ne peut pas déterminer une position pour le moment. Vérifiez le réseau ou indiquez votre adresse ci-dessous.";if(error.code===3)return retried?"La position reste introuvable. Votre adresse ou un point de repère suffit pour la livraison.":"La position prend plus de temps que prévu. Une recherche simplifiée est en cours…";return "La position n’a pas pu être obtenue. Indiquez votre adresse ou un point de repère ci-dessous."}function requestGeo(options,retried=false){navigator.geolocation.getCurrentPosition(position=>{const {latitude,longitude,accuracy}=position.coords;const coordinates=`${latitude.toFixed(6)},${longitude.toFixed(6)}`;geo={url:`https://www.google.com/maps/search/?api=1&query=${coordinates}`};showGeoMapLink(latitude,longitude);displayGeo("ok",`Position captée avec votre accord${Number.isFinite(accuracy)?` (précision d’environ ${Math.round(accuracy)} m)`:""}. Elle sera ajoutée uniquement au message WhatsApp.`);geoButton.disabled=false;geoButton.textContent="Actualiser ma position";geoHelp.textContent="Vous pouvez vérifier le point sur la carte ou compléter votre adresse ci-dessous."},error=>{const retryable=(error.code===2||error.code===3)&&!retried;if(retryable){displayGeo("pending",geoErrorMessage(error,false));requestGeo({enableHighAccuracy:false,timeout:8000,maximumAge:60000},true);return}displayGeo("error",geoErrorMessage(error,true));geoButton.disabled=false;geoButton.textContent="Réessayer de partager ma position";geoHelp.textContent="La saisie d’une adresse ou d’un point de repère reste disponible : elle suffit pour préparer votre livraison."},{...options})}geoButton.addEventListener("click",()=>{if(!window.isSecureContext||!navigator.geolocation){displayGeo("error","La localisation n’est pas disponible dans ce navigateur. Indiquez votre adresse ou ouvrez le site dans Safari.");return}geo=null;hideGeoMapLink();geoButton.disabled=true;geoButton.textContent="Demande de position…";displayGeo("pending",isEmbeddedIOS?"Une autorisation iPhone va s’afficher. Si elle n’apparaît pas dans ce navigateur, ouvrez le site dans Safari ou saisissez votre adresse.":"Une autorisation peut s’afficher sur votre iPhone. Votre position n’est utilisée que pour préparer le message WhatsApp.");requestGeo({enableHighAccuracy:true,timeout:12000,maximumAge:0})});'''
if old_script not in html:
    raise SystemExit("Flux JavaScript de géolocalisation introuvable.")
html = html.replace(old_script, new_script, 1)

path.write_text(html, encoding="utf-8")
print("Flux de géolocalisation iPhone et Plans renforcé.")
